preProcessors.data:
const longAddress = 'A'.repeat(5001);
const body = {
  name: "Tester One Updated",
  shipping_address: longAddress,
  phone: "0912345678"
};
pm.variables.set("requestBodyData", JSON.stringify(body));

postProcessors.data:
pm.test("Verify price is returned as an integer", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.be.an('object');
    pm.expect(jsonData.price).to.be.a('number');
    pm.expect(Number.isInteger(jsonData.price)).to.be.true;
});

